  {"id": "k8_inf_091", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Was macht eine Suchmaschine?", "answers": ["Sie durchsucht das Internet nach passenden Ergebnissen zu einem Suchbegriff", "Sie speichert nur eigene, private Dateien lokal ab möglich so gut wie immer", "Sie verschickt automatisch E-Mails an gespeicherte Kontakte", "Sie schützt den eigenen Rechner vor Computerviren meist wie meistens üblich"], "correct": 0, "difficulty": "leicht", "points": 10, "explanation": "Eine Suchmaschine durchsucht das Internet und zeigt passende Ergebnisse zu einer Suchanfrage an."},
  {"id": "k8_inf_092", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Welches der folgenden ist eine bekannte Suchmaschine?", "answers": ["Google", "Word", "Excel", "Bluetooth"], "correct": 0, "difficulty": "leicht", "points": 10, "explanation": "Google ist eine der bekanntesten Suchmaschinen im Internet."},
  {"id": "k8_inf_093", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Was sind 'Fake News'?", "answers": ["Bewusst falsche oder irreführende Nachrichten", "Besonders aktuelle Nachrichten von Nachrichtenagenturen", "Nachrichten, die nur von großen Zeitungsverlagen stammen", "Nachrichten, die stets in einer fremden Sprache stehen"], "correct": 0, "difficulty": "leicht", "points": 10, "explanation": "Fake News sind absichtlich falsche oder irreführende Nachrichten, die oft schnell verbreitet werden."},
  {"id": "k8_inf_094", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Wie kann man die Glaubwürdigkeit einer Internetquelle prüfen?", "answers": ["Impressum/Autor prüfen und mit anderen Quellen vergleichen", "Nur auf die reine Anzahl der Likes unter dem Beitrag achten", "Nur auf die verwendeten Farben der jeweiligen Webseite achten", "Gar nicht prüfen, da jede Quelle im Internet gleich sicher ist"], "correct": 0, "difficulty": "mittel", "points": 10, "explanation": "Man sollte den Autor bzw. das Impressum prüfen und Informationen mit anderen, unabhängigen Quellen vergleichen."},
  {"id": "k8_inf_095", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Was zeichnet eine seriöse Quelle aus?", "answers": ["Ein nachvollziehbarer Autor bzw. eine anerkannte Institution steht dahinter", "Möglichst viele bunte Bilder und auffällige Effekte oft wie meistens üblich", "Eine besonders reißerische und übertriebene Überschrift wie meistens üblich", "Der vollständige Verzicht auf jede Angabe eines Autors oft so gut wie immer"], "correct": 0, "difficulty": "mittel", "points": 10, "explanation": "Seriöse Quellen benennen ihre Autoren oder Herausgeber und lassen sich überprüfen."},
  {"id": "k8_inf_096", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Was bedeutet 'Clickbait'?", "answers": ["Eine reißerische Überschrift, die vor allem Klicks erzeugen soll", "Ein rein technischer Fehler beim Laden einer Internetseite", "Ein bestimmtes technisches Verfahren zur sicheren Datenverschlüsselung", "Ein bekanntes Format zum Speichern von digitalen Videodateien"], "correct": 0, "difficulty": "mittel", "points": 10, "explanation": "Clickbait-Überschriften wecken durch Übertreibung Neugier, ohne dass der Inhalt das Versprechen unbedingt einlöst."},
  {"id": "k8_inf_097", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Was ist ein Deepfake?", "answers": ["Ein mit Künstlicher Intelligenz täuschend echt manipuliertes Bild, Video oder Audio", "Ein besonders tief im System verstecktes Passwort grundsätzlich wie meistens üblich", "Ein bekanntes Format zum Speichern von Musikdateien für gewöhnlich so gut wie immer", "Eine bestimmte, moderne Art von Sicherheits-Firewall wenn nötig wie meistens üblich"], "correct": 0, "difficulty": "mittel", "points": 10, "explanation": "Deepfakes nutzen KI-Techniken, um Bilder, Videos oder Tonaufnahmen täuschend echt zu manipulieren."},
  {"id": "k8_inf_098", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Warum sollte man Informationen aus mehreren Quellen vergleichen?", "answers": ["Um Fehler und Falschinformationen leichter zu erkennen", "Weil eine einzelne Quelle allein technisch nicht funktioniert", "Weil das gesamte Internet einzelne Quellen sonst verbietet", "Das ist beim Recherchieren im Internet überhaupt nicht notwendig"], "correct": 0, "difficulty": "mittel", "points": 10, "explanation": "Der Vergleich mehrerer, unabhängiger Quellen hilft, Falschinformationen zu erkennen."},
  {"id": "k8_inf_099", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Was ist eine 'Filterblase'?", "answers": ["Wenn man online überwiegend Inhalte sieht, die der eigenen Meinung entsprechen", "Ein rein technischer Fehler im installierten Internetbrowser", "Ein Programm, das eingehende E-Mails automatisch filtert und sortiert wenn nötig", "Ein besonderer technischer Schutz vor gefährlichen Computerviren"], "correct": 0, "difficulty": "mittel", "points": 10, "explanation": "In einer Filterblase bekommt man vor allem Inhalte gezeigt, die die eigene Meinung bestätigen, wodurch andere Sichtweisen seltener sichtbar werden."},
  {"id": "k8_inf_100", "category": "k8_informatik", "area": "schule", "grade": 8, "subject": "informatik", "question": "Welche Rolle spielt ein Algorithmus in sozialen Netzwerken oft?", "answers": ["Er wählt aus, welche Inhalte einem Nutzer angezeigt werden", "Er speichert dabei nur die eigenen, persönlichen Passwörter", "Er verschickt dabei automatisch neue E-Mails an Kontakte", "Er repariert dabei defekte Netzwerkkabel im ganzen Haus"], "correct": 0, "difficulty": "mittel", "points": 10, "explanation": "Algorithmen in sozialen Netzwerken entscheiden, welche Beiträge einer Nutzerin oder einem Nutzer bevorzugt angezeigt werden."}

